SELECT s.city, CASE WHEN s.sqft >= 12566 THEN 'high' WHEN s.sqft >= 7659 THEN 'mid' ELSE 'low' END AS sqft_bucket, SUM(CASE WHEN o.status = 'CANCELLED' THEN o.discount ELSE 0 END) AS cancelled_discount FROM orders o LEFT JOIN customers c ON o.customer_id = c.id INNER JOIN stores s ON o.store_id = s.id WHERE s.city = 'Chiang Mai' GROUP BY s.city, CASE WHEN s.sqft >= 12566 THEN 'high' WHEN s.sqft >= 7659 THEN 'mid' ELSE 'low' END ORDER BY cancelled_discount DESC;
